CREATE TABLE `health_alerts` (
  `alert_id` int NOT NULL AUTO_INCREMENT COMMENT 'Alert ID',
  `user_id` int NOT NULL COMMENT 'User ID',
  `monitor_id` int DEFAULT NULL COMMENT 'Monitoring data ID',
  `alert_type` varchar(50) NOT NULL COMMENT 'Alert type',
  `alert_level` varchar(20) NOT NULL COMMENT 'Alert level: info/warning/critical',
  `alert_title` varchar(200) NOT NULL COMMENT 'Alert title',
  `alert_content` text NOT NULL COMMENT 'Alert content',
  `data_type` varchar(50) DEFAULT NULL COMMENT 'Related data type',
  `data_value` varchar(100) DEFAULT NULL COMMENT 'Related data value',
  `normal_range` varchar(100) DEFAULT NULL COMMENT 'Normal range',
  `is_read` tinyint DEFAULT '0' COMMENT 'Is read: 1=yes/0=no',
  `is_handled` tinyint DEFAULT '0' COMMENT 'Is handled: 1=yes/0=no',
  `handle_result` text COMMENT 'Handle result',
  `notify_user` tinyint DEFAULT '1' COMMENT 'Notify user: 1=yes/0=no',
  `notify_doctor` tinyint DEFAULT '0' COMMENT 'Notify doctor: 1=yes/0=no',
  `notify_time` datetime DEFAULT NULL COMMENT 'Notify time',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Create time',
  `handle_time` datetime DEFAULT NULL COMMENT 'Handle time',
  PRIMARY KEY (`alert_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_alert_level` (`alert_level`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Health alerts table';
