DROP TABLE IF EXISTS `health_checkin`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `health_checkin` (
  `checkin_id` int NOT NULL AUTO_INCREMENT COMMENT '鎵撳崱ID',
  `user_id` int NOT NULL COMMENT '鐢ㄦ埛ID',
  `checkin_date` date NOT NULL COMMENT '鎵撳崱鏃ユ湡',
  `checkin_time` time DEFAULT NULL COMMENT '鎵撳崱鏃堕棿',
  `overall_feeling` varchar(50) DEFAULT NULL COMMENT '鏁翠綋鎰熷彈(鑹ソ/涓€鑸?涓嶉€?',
  `sleep_quality` varchar(20) DEFAULT NULL COMMENT '鐫＄湢璐ㄩ噺(浼樼/鑹ソ/涓€鑸?宸?',
  `sleep_hours` decimal(4,1) DEFAULT NULL COMMENT '鐫＄湢鏃堕暱(灏忔椂)',
