INSERT INTO `health_records` VALUES
(1315,33,'体检报告','2025年度全面体检报告','2025-04-10','张医生','血压145/95mmHg偏高，BMI 26.8超重，空腹血糖5.9mmol/L接近临界值。心率82次/分，肝功能轻度异常。建议控制体重，低盐低脂饮食，定期复查血压和血糖。',1,'2026-04-23 08:00:00',NULL,NULL),
(1316,33,'血检报告','血常规及生化检查','2025-05-15','李医生','血红蛋白110g/L偏低，提示轻度贫血。白细胞计数5.6x10^9/L正常。血小板210x10^9/L正常。铁蛋白18ng/mL偏低，建议补充铁剂和含铁食物。',1,'2026-04-23 08:00:00',NULL,NULL),
(1317,33,'血脂检查','血脂四项检查报告','2025-06-20','王医生','总胆固醇6.2mmol/L偏高，低密度脂蛋白3.8mmol/L偏高，甘油三酯2.5mmol/L偏高，高密度脂蛋白1.0mmol/L偏低。建议低脂饮食，增加有氧运动。',1,'2026-04-23 08:00:00',NULL,NULL),
(1318,33,'肝功能','肝功能五项检查','2025-07-10','刘医生','ALT 65U/L明显升高，AST 52U/L轻度升高，GGT 78U/L升高。总胆红素正常，白蛋白正常。可能与长期饮酒有关，建议戒酒，一个月后复查。',1,'2026-04-23 08:00:00',NULL,NULL),
(1319,33,'心电图','常规心电图检查','2025-08-05','赵医生','窦性心律不齐，心率82次/分。偶发房性早搏，ST段无明显改变。建议避免过度劳累和情绪激动，定期随访。',1,'2026-04-23 08:00:00',NULL,NULL),
(1320,33,'肾功能','肾功能三项检查','2025-09-15','陈医生','肌酐95umol/L正常，尿素氮5.8mmol/L正常，尿酸450umol/L偏高。高尿酸血症，需控制高嘌呤食物摄入，多饮水，避免饮酒。',1,'2026-04-23 08:00:00',NULL,NULL),
(1321,36,'体检报告','2025年度体检报告','2025-03-20','张医生','整体健康良好。BMI 22.5正常，血压118/76mmHg正常，心率70次/分。各项基本指标均在正常范围内。建议保持当前健康生活方式。',0,'2026-04-23 08:00:00',NULL,NULL),
