(1340,40,'血压监测','24小时动态血压监测','2025-10-05','冯医生','白天平均血压155/98mmHg，夜间140/88mmHg，24小时平均150/95mmHg。血压昼夜节律消失。确诊高血压2级，建议启动降压药物治疗。',1,'2026-04-23 08:00:00',NULL,NULL),
(1341,41,'体检报告','2025年度体检报告','2025-04-15','张医生','体重偏轻BMI 17.8，血压100/65mmHg偏低。血红蛋白105g/L偏低，白蛋白35g/L偏低。提示轻度营养不良，建议加强营养摄入。',1,'2026-04-23 08:00:00',NULL,NULL),
(1342,41,'血检报告','贫血相关检查','2025-05-20','李医生','血红蛋白105g/L偏低，铁蛋白12ng/mL偏低，血清铁8umol/L偏低。诊断缺铁性贫血，建议补充铁剂，多食用含铁丰富食物。',1,'2026-04-23 08:00:00',NULL,NULL),
(1343,41,'甲状腺功能','甲功五项检查','2025-06-25','王医生','TSH 2.1mIU/L正常，FT3 4.8pmol/L正常，FT4 16.5pmol/L正常，TPOAb阴性，TgAb阴性。甲状腺功能正常。',0,'2026-04-23 08:00:00',NULL,NULL),
(1344,41,'骨密度','骨密度检测报告','2025-08-10','郑医生','腰椎T值-2.2，股骨颈T值-2.0。接近骨质疏松诊断标准，骨量严重减少。建议内分泌科就诊，补充钙剂和维生素D，必要时药物治疗。',1,'2026-04-23 08:00:00',NULL,NULL),
(1345,41,'肺功能','肺功能检测报告','2025-09-15','卫医生','FVC 85%预计值偏低，FEV1 80%预计值偏低，FEV1/FVC 94%正常。小气道功能FEF25-75%为65%轻度降低。提示限制性通气功能障碍可能。',1,'2026-04-23 08:00:00',NULL,NULL),
(1346,32,'眼底检查','眼底照相检查报告','2026-01-10','孙医生','双眼底动脉硬化II级，动静脉交叉压迹明显。右眼底见2处微血管瘤，左眼底见1处点状出血。与高血压、血脂异常相关，建议3个月后复查。',1,'2026-04-23 08:00:00',NULL,NULL),
(1347,32,'尿常规','尿液分析报告','2026-01-20','吴医生','尿蛋白(+)，尿糖(-)。红细胞0-2/HP正常，白细胞2-4/HP正常。尿蛋白阳性需排除肾脏疾病，建议2周后复查尿常规。',1,'2026-04-23 08:00:00',NULL,NULL),
(1348,32,'甲状腺功能','甲功五项检查','2026-02-05','王医生','TSH 0.3mIU/L偏低，FT3 8.2pmol/L偏高，FT4 28pmol/L偏高。提示甲状腺功能亢进可能，建议内分泌科就诊，完善甲状腺彩超和摄碘率检查。',1,'2026-04-23 08:00:00',NULL,NULL),
(1349,32,'X光检查','颈椎正侧位X光','2026-02-20','周医生','颈椎生理曲度变直，C3-C7椎体后缘骨质增生。C5-C6椎间隙明显变窄，椎间孔狭窄。诊断颈椎病，建议避免长时间低头，颈椎理疗。',1,'2026-04-23 08:00:00',NULL,NULL),
(1350,32,'心脏彩超','心脏超声检查报告','2026-03-10','赵医生','左室内径正常，室壁运动协调。二尖瓣轻度返流，三尖瓣微量返流。左室舒张功能减低(E/A<1)，射血分数55%临界值。建议心内科随诊。',1,'2026-04-23 08:00:00',NULL,NULL);
/*!40000 ALTER TABLE `health_records` ENABLE KEYS */;
